import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Button,
  Input,
  Select,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type { TrialBalanceStatementRow } from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel, monthStartEnd } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { navigateInAppPath } from '../../../router/navigateInAppPath';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './CanDoiPhatSinhPage.module.css';

const TEST_ID = 'rpt-can-doi-phat-sinh';
const PAGE_ID = 'baocao-can-doi-phat-sinh';
const TITLE = 'Bảng cân đối phát sinh';

type RowTag = 'Leaf' | 'Parent' | 'Total' | 'Blank';

const ACCOUNT_LEVEL_OPTIONS = [
  { value: '0', label: 'Tất cả' },
  ...Array.from({ length: 9 }, (_, i) => ({
    value: String(i + 1),
    label: String(i + 1),
  })),
];

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function mapRowTag(
  raw: TrialBalanceStatementRow['rowTag'],
  isTotal?: boolean,
  isParent?: boolean,
): RowTag {
  if (raw === 'Blank') return 'Blank';
  if (raw === 'Total' || isTotal) return 'Total';
  if (raw === 'Parent' || isParent) return 'Parent';
  return 'Leaf';
}

function normalizeItems(items: TrialBalanceStatementRow[]): TrialBalanceStatementRow[] {
  return items.map(r => {
    const rowTag = mapRowTag(r.rowTag, r.isTotal, r.isParent);
    const isTotal = rowTag === 'Total' || Boolean(r.isTotal);
    const isParent = rowTag === 'Parent' || Boolean(r.isParent);
    const isBlank = rowTag === 'Blank';
    return {
      ...r,
      rowTag,
      isTotal,
      isParent,
      isBold: isBlank ? false : Boolean(r.isBold) || isTotal || isParent,
      accountCode: r.accountCode ?? '',
      accountCodeDisplay: r.accountCodeDisplay ?? '',
      accountName: r.accountName ?? '',
      accountLevel: Number(r.accountLevel ?? 0),
      openingDebit: Number(r.openingDebit ?? 0),
      openingCredit: Number(r.openingCredit ?? 0),
      periodDebit: Number(r.periodDebit ?? 0),
      periodCredit: Number(r.periodCredit ?? 0),
      ytdDebit: Number(r.ytdDebit ?? 0),
      ytdCredit: Number(r.ytdCredit ?? 0),
      closingDebit: Number(r.closingDebit ?? 0),
      closingCredit: Number(r.closingCredit ?? 0),
    };
  });
}

function rowClass(tag: RowTag): string {
  if (tag === 'Total') return styles.rowToneTotal;
  if (tag === 'Blank') return styles.rowToneBlank;
  if (tag === 'Parent') return `${styles.rowToneParent} ${styles.rowDrillable}`;
  return `${styles.rowToneLeaf} ${styles.rowDrillable}`;
}

function moneyCell(tag: RowTag, value: number): string {
  if (tag === 'Blank') return '';
  return formatVnd(value);
}

const CanDoiPhatSinhPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const initial = monthStartEnd();

  const [fromDate, setFromDate] = useState(initial.fromDate);
  const [toDate, setToDate] = useState(initial.toDate);
  const [accountLevel, setAccountLevel] = useState(0);
  const [includeYtdTurnover, setIncludeYtdTurnover] = useState(true);

  const [items, setItems] = useState<TrialBalanceStatementRow[]>([]);
  const [appliedFrom, setAppliedFrom] = useState('');
  const [appliedTo, setAppliedTo] = useState('');
  const [appliedLevel, setAppliedLevel] = useState(0);
  const [appliedIncludeYtd, setAppliedIncludeYtd] = useState(true);
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const [contextMenu, setContextMenu] = useState<{
    x: number;
    y: number;
    row: TrialBalanceStatementRow;
  } | null>(null);
  const { showTableLoading } = useCatalogTableBusy(loading);

  const showYtdCols = hasViewed ? appliedIncludeYtd : includeYtdTurnover;

  const summary = useMemo(() => {
    if (!hasViewed) return null;
    const total = items.find(r => mapRowTag(r.rowTag, r.isTotal, r.isParent) === 'Total');
    if (!total) return null;
    return {
      openingDebit: Number(total.openingDebit ?? 0),
      openingCredit: Number(total.openingCredit ?? 0),
      periodDebit: Number(total.periodDebit ?? 0),
      periodCredit: Number(total.periodCredit ?? 0),
      ytdDebit: Number(total.ytdDebit ?? 0),
      ytdCredit: Number(total.ytdCredit ?? 0),
      closingDebit: Number(total.closingDebit ?? 0),
      closingCredit: Number(total.closingCredit ?? 0),
    };
  }, [hasViewed, items]);

  const leafCount = useMemo(
    () => items.filter(r => mapRowTag(r.rowTag, r.isTotal, r.isParent) === 'Leaf').length,
    [items],
  );

  useEffect(() => {
    if (!contextMenu) return undefined;
    const close = () => setContextMenu(null);
    window.addEventListener('click', close);
    return () => window.removeEventListener('click', close);
  }, [contextMenu]);

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    if (!fromDate.trim() || !toDate.trim()) {
      setFilterError('Chọn khoảng ngày');
      dispatchAppToast(dispatch, { message: 'Chọn khoảng ngày', type: 'error' });
      return;
    }
    if (toDate < fromDate) {
      setFilterError('Đến ngày phải ≥ Từ ngày');
      dispatchAppToast(dispatch, { message: 'Đến ngày phải ≥ Từ ngày', type: 'error' });
      return;
    }

    const level = Number.isFinite(accountLevel) && accountLevel >= 0 ? accountLevel : 0;

    setLoading(true);
    analyticsService
      .getTrialBalanceStatement({
        fromDate: fromDate.trim(),
        toDate: toDate.trim(),
        accountLevel: level,
        includeYtdTurnover,
        pageSize: 0,
      })
      .then(report => {
        setItems(normalizeItems(report.items ?? []));
        setAppliedFrom(fromDate.trim());
        setAppliedTo(toDate.trim());
        setAppliedLevel(level);
        setAppliedIncludeYtd(includeYtdTurnover);
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được bảng cân đối phát sinh'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [accountLevel, dispatch, fromDate, includeYtdTurnover, toDate]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    const next = monthStartEnd();
    setFromDate(next.fromDate);
    setToDate(next.toDate);
    setAccountLevel(0);
    setIncludeYtdTurnover(true);
    setFilterError('');
  }, []);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading || !appliedFrom || !appliedTo) return;
    const fileName = `can-doi-phat-sinh_${appliedFrom}_${appliedTo}.xlsx`;
    void exportExcel(
      '/accounting/trial-balance-statement/export-excel',
      {
        fromDate: appliedFrom,
        toDate: appliedTo,
        accountLevel: appliedLevel,
        includeYtdTurnover: appliedIncludeYtd,
        pageSize: 0,
      },
      fileName,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedFrom, appliedIncludeYtd, appliedLevel, appliedTo, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    window.print();
  }, []);

  const drillToTForm = useCallback(
    (row: TrialBalanceStatementRow) => {
      if (!hasViewed) return;
      const tag = mapRowTag(row.rowTag, row.isTotal, row.isParent);
      if (tag === 'Total') {
        dispatchAppToast(dispatch, {
          message: 'Không mở chi tiết từ hàng tổng',
          type: 'info',
        });
        return;
      }
      if (tag === 'Blank') return;
      const code = (row.accountCode ?? '').trim();
      if (!code || !appliedFrom || !appliedTo) return;
      const qs = new URLSearchParams({
        accountCode: code,
        fromDate: appliedFrom,
        toDate: appliedTo,
      });
      navigateInAppPath(`/baocao/so-tong-hop-chu-t?${qs.toString()}`, navigate);
    },
    [appliedFrom, appliedTo, dispatch, hasViewed, navigate],
  );

  const drillToDetail = useCallback(
    (row: TrialBalanceStatementRow) => {
      if (!hasViewed) return;
      const tag = mapRowTag(row.rowTag, row.isTotal, row.isParent);
      if (tag === 'Total') {
        dispatchAppToast(dispatch, {
          message: 'Không mở chi tiết từ hàng tổng',
          type: 'info',
        });
        return;
      }
      if (tag === 'Blank') return;
      const code = (row.accountCode ?? '').trim();
      if (!code || !appliedFrom || !appliedTo) return;
      const qs = new URLSearchParams({
        accountCode: code,
        fromDate: appliedFrom,
        toDate: appliedTo,
      });
      navigateInAppPath(`/baocao/so-chi-tiet?${qs.toString()}`, navigate);
    },
    [appliedFrom, appliedTo, dispatch, hasViewed, navigate],
  );

  const onRowDoubleClick = useCallback(
    (e: React.MouseEvent, row: TrialBalanceStatementRow) => {
      if (e.ctrlKey || e.metaKey) {
        drillToDetail(row);
        return;
      }
      drillToTForm(row);
    },
    [drillToDetail, drillToTForm],
  );

  const onRowContextMenu = useCallback(
    (e: React.MouseEvent, row: TrialBalanceStatementRow) => {
      const tag = mapRowTag(row.rowTag, row.isTotal, row.isParent);
      if (tag === 'Blank') return;
      if (tag === 'Total') {
        e.preventDefault();
        dispatchAppToast(dispatch, {
          message: 'Không mở chi tiết từ hàng tổng',
          type: 'info',
        });
        return;
      }
      e.preventDefault();
      setContextMenu({ x: e.clientX, y: e.clientY, row });
    },
    [dispatch],
  );

  const exportDisabled = !hasViewed || loading || !appliedFrom;

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-excel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: exportDisabled,
        onClick: handleExport,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [exportDisabled, handleExport, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle =
    hasViewed && appliedFrom && appliedTo
      ? `Từ: ${formatDate(appliedFrom)} đến ngày ${formatDate(appliedTo)}`
      : undefined;

  const listBody = showTableLoading ? null : (
    <div className={erp.tableWrapper}>
      {subtitle ? (
        <div data-testid={`${TEST_ID}-subtitle`} className={reportStyles.subtitle} style={{ marginBottom: '0.5rem' }}>
          {subtitle}
        </div>
      ) : null}
      <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Tài khoản</th>
            <th>Tên tài khoản</th>
            <th className={reportStyles.colRight}>Nợ đầu kỳ</th>
            <th className={reportStyles.colRight}>Có đầu kỳ</th>
            <th className={reportStyles.colRight}>Phát sinh nợ</th>
            <th className={reportStyles.colRight}>Phát sinh có</th>
            {showYtdCols ? (
              <>
                <th className={reportStyles.colRight}>Ps Nợ LK</th>
                <th className={reportStyles.colRight}>Ps Có LK</th>
              </>
            ) : null}
            <th className={reportStyles.colRight}>Dư nợ cuối kỳ</th>
            <th className={reportStyles.colRight}>Dư có cuối kỳ</th>
          </tr>
        </thead>
        <tbody>
          {!hasViewed
            ? null
            : items.map((row, index) => {
                const tag = mapRowTag(row.rowTag, row.isTotal, row.isParent);
                const isTotal = tag === 'Total';
                const isParent = tag === 'Parent';
                const isBlank = tag === 'Blank';
                const drillable = tag === 'Leaf' || tag === 'Parent';
                return (
                  <tr
                    key={`${tag}|${row.accountCode ?? 'T'}|${isParent ? 'P' : 'L'}|${index}`}
                    className={rowClass(tag)}
                    data-testid={`${TEST_ID}-row-${index}`}
                    data-row-tag={tag}
                    data-is-parent={isParent ? '1' : '0'}
                    data-is-total={isTotal ? '1' : '0'}
                    data-account-code={row.accountCode ?? ''}
                    data-drillable={drillable ? '1' : '0'}
                    title={
                      drillable
                        ? 'Double-click: sổ chữ T · Chuột phải: sổ chi tiết'
                        : undefined
                    }
                    onDoubleClick={e => onRowDoubleClick(e, row)}
                    onContextMenu={e => onRowContextMenu(e, row)}
                  >
                    <td className={styles.cellIndent}>
                      {isTotal || isBlank ? '' : (row.accountCodeDisplay ?? row.accountCode ?? '')}
                    </td>
                    <td>{isBlank ? '' : (row.accountName ?? '')}</td>
                    <td className={reportStyles.colRight}>{moneyCell(tag, row.openingDebit ?? 0)}</td>
                    <td className={reportStyles.colRight}>{moneyCell(tag, row.openingCredit ?? 0)}</td>
                    <td className={reportStyles.colRight}>{moneyCell(tag, row.periodDebit ?? 0)}</td>
                    <td className={reportStyles.colRight}>{moneyCell(tag, row.periodCredit ?? 0)}</td>
                    {showYtdCols ? (
                      <>
                        <td className={reportStyles.colRight}>{moneyCell(tag, row.ytdDebit ?? 0)}</td>
                        <td className={reportStyles.colRight}>{moneyCell(tag, row.ytdCredit ?? 0)}</td>
                      </>
                    ) : null}
                    <td className={reportStyles.colRight}>{moneyCell(tag, row.closingDebit ?? 0)}</td>
                    <td className={reportStyles.colRight}>{moneyCell(tag, row.closingCredit ?? 0)}</td>
                  </tr>
                );
              })}
        </tbody>
      </table>
      {hasViewed && leafCount === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
    </div>
  );

  const footer =
    hasViewed && summary ? (
      <div className={styles.summaryBar} data-testid={`${TEST_ID}-summary`}>
        <span>Nợ ĐK: {formatVnd(summary.openingDebit)}</span>
        <span>Có ĐK: {formatVnd(summary.openingCredit)}</span>
        <span>PS nợ: {formatVnd(summary.periodDebit)}</span>
        <span>PS có: {formatVnd(summary.periodCredit)}</span>
        {appliedIncludeYtd ? (
          <>
            <span>Ps Nợ LK: {formatVnd(summary.ytdDebit)}</span>
            <span>Ps Có LK: {formatVnd(summary.ytdCredit)}</span>
          </>
        ) : null}
        <span>Dư nợ CK: {formatVnd(summary.closingDebit)}</span>
        <span>Dư có CK: {formatVnd(summary.closingCredit)}</span>
      </div>
    ) : undefined;

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-balance-scale' }}
        listTitle={TITLE}
        filterMaxWidthPx={1400}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        footer={footer}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-fromDate`}>
              <Input
                type="date"
                label="Từ ngày"
                value={fromDate}
                onChange={e => setFromDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-from`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-toDate`}>
              <Input
                type="date"
                label="Đến ngày"
                value={toDate}
                onChange={e => setToDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-to`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-accountLevel`}>
              <Select
                label="Bậc tài khoản"
                value={String(accountLevel)}
                onChange={e => {
                  const n = Number(e.target.value);
                  setAccountLevel(Number.isFinite(n) && n >= 0 ? n : 0);
                }}
                options={ACCOUNT_LEVEL_OPTIONS}
                size="small"
                data-testid={`${TEST_ID}-field-level`}
              />
            </div>
            <div
              className={styles.lkCheck}
              data-testid={`${TEST_ID}-field-includeYtdTurnover`}
            >
              <input
                id={`${TEST_ID}-lk`}
                type="checkbox"
                checked={includeYtdTurnover}
                onChange={e => setIncludeYtdTurnover(e.target.checked)}
                data-testid={`${TEST_ID}-field-lk`}
              />
              <label htmlFor={`${TEST_ID}-lk`}>Lũy kế</label>
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div className={styles.filterError} data-testid={`${TEST_ID}-filter-error`}>
                {filterError}
              </div>
            ) : null}
          </>
        )}
      >
        {listBody}
      </LinPageLayout>
      {contextMenu ? (
        <div
          className={styles.contextMenu}
          style={{ left: contextMenu.x, top: contextMenu.y }}
          data-testid={`${TEST_ID}-context-menu`}
          onClick={e => e.stopPropagation()}
        >
          <button
            type="button"
            data-testid={`${TEST_ID}-drill-t-form`}
            onClick={() => {
              drillToTForm(contextMenu.row);
              setContextMenu(null);
            }}
          >
            Sổ chữ T
          </button>
          <button
            type="button"
            data-testid={`${TEST_ID}-drill-detail`}
            onClick={() => {
              drillToDetail(contextMenu.row);
              setContextMenu(null);
            }}
          >
            Sổ chi tiết
          </button>
        </div>
      ) : null}
    </div>
  );
};

export default CanDoiPhatSinhPage;
